package com.yeyamo_mobile.api.messaging_service.infrastructure.persistence;
import java.time.Instant;import java.util.*;import org.springframework.data.cassandra.core.mapping.*;import com.yeyamo_mobile.api.messaging_service.domain.MessageType;
@Table("messages_by_id")public class MessageByIdEntity{@PrimaryKey("message_id")private UUID messageId;@Column("conversation_id")private UUID conversationId;@Column("sent_at")private Instant sentAt;@Column("sender_id")private String senderId;@Column("client_message_id")private String clientMessageId;@Column("message_type")private MessageType messageType;@Column private String body;@Column("attachment_ids")private List<UUID>attachmentIds;@Column("reply_to_message_id")private UUID replyToMessageId;@Column("edited_at")private Instant editedAt;@Column("deleted_at")private Instant deletedAt;
 public static MessageByIdEntity from(MessageEntity m){var x=new MessageByIdEntity();x.sync(m);return x;}public void sync(MessageEntity m){messageId=m.getMessageId();conversationId=m.getConversationId();sentAt=m.getSentAt();senderId=m.getSenderId();clientMessageId=m.getClientMessageId();messageType=m.getMessageType();body=m.getBody();attachmentIds=m.getAttachmentIds();replyToMessageId=m.getReplyToMessageId();editedAt=m.getEditedAt();deletedAt=m.getDeletedAt();}
 public void edit(String value){body=value;editedAt=Instant.now();}public void delete(){body=null;attachmentIds=List.of();deletedAt=Instant.now();}
 public UUID getMessageId(){return messageId;}public UUID getConversationId(){return conversationId;}public Instant getSentAt(){return sentAt;}public String getSenderId(){return senderId;}public String getClientMessageId(){return clientMessageId;}public MessageType getMessageType(){return messageType;}public String getBody(){return body;}public List<UUID>getAttachmentIds(){return attachmentIds;}public UUID getReplyToMessageId(){return replyToMessageId;}public Instant getEditedAt(){return editedAt;}public Instant getDeletedAt(){return deletedAt;}}
